(1070138, 129047, 18799, '<td valign="top">I think you needed to shoot this either earlier at night, or with more exposure.  It looks like it''s floating in space.  Too bad because the colors are great.</td>', 'I think you needed to shoot this either earlier at night, or with more exposure.  It looks like it''s floating in space.  Too bad because the colors are great.', '2004-12-20 07:26:04.000000', NULL, 1),
(1070141, 129266, 18799, '<td valign="top">"classy?"</td>', '"classy?"', '2004-12-20 07:28:21.000000', NULL, 1),
(1070143, 129229, 18799, '<td valign="top">The flash overpowered the subject here.</td>', 'The flash overpowered the subject here.', '2004-12-20 07:29:42.000000', NULL, 1),
(1070146, 128950, 18799, '<td valign="top">Nice try but this doesn''t meet the intent of the challenge IMO</td>', 'Nice try but this doesn''t meet the intent of the challenge IMO', '2004-12-20 07:30:58.000000', NULL, 1),
(1070148, 129008, 18799, '<td valign="top">The image isn''t quite sharp, and the cloth is way too busy and distracting IMO</td>', 'The image isn''t quite sharp, and the cloth is way too busy and distracting IMO', '2004-12-20 07:32:13.000000', NULL, 1),
(1070149, 128998, 18799, '<td valign="top">The photo is nice enough.  The border, however, is another story.  A border should not overpower the subject of the photo - this one does.</td>', 'The photo is nice enough.  The border, however, is another story.  A border should not overpower the subject of the photo - this one does.', '2004-12-20 07:34:07.000000', NULL, 1),
(1070151, 129396, 18799, '<td valign="top">Hopefully you will enlighten as to how this is a "classy holiday decoration"</td>', 'Hopefully you will enlighten as to how this is a "classy holiday decoration"', '2004-12-20 07:36:22.000000', NULL, 1),
(1070154, 129366, 18799, '<td valign="top">I like this.  Two things I would have done differently though.  Since this is advanced editing, I would have cloned out your image in the bulb, and I would have reduced the brightness of the light area in lower center.</td>', 'I like this.  Two things I would have done differently though.  Since this is advanced editing, I would have cloned out your image in the bulb, and I would have reduced the brightness of the light area in lower center.', '2004-12-20 07:42:44.000000', NULL, 1),
(1070163, 128998, 27562, '<td valign="top">I think the red border distracts attention away from the image.  If you really wanted red, maybe you could have sampled the red in the ribbons &amp; used that red.  Good work.</td>', 'I think the red border distracts attention away from the image.  If you really wanted red, maybe you could have sampled the red in the ribbons & used that red.  Good work.', '2004-12-20 07:49:23.000000', NULL, 1),
