(1070169, 129283, 27562, '<td valign="top">Really nice colors, but I think it has been softened a little too much.  Good work.<br/>P.S. could have been used for hidden face ;-)</td>', 'Really nice colors, but I think it has been softened a little too much.  Good work.P.S. could have been used for hidden face ;-)', '2004-12-20 07:52:29.000000', NULL, 1),
(1070173, 129479, 27562, '<td valign="top">Really nice composition and great relections, but I wish the image would have been sharper.  Good Job.</td>', 'Really nice composition and great relections, but I wish the image would have been sharper.  Good Job.', '2004-12-20 07:53:38.000000', NULL, 1),
