(1071058, 128987, 30214, '<td valign="top">I love it</td>', 'I love it', '2004-12-20 17:16:01.000000', NULL, 1),
(1071094, 129120, 21124, '<td valign="top">After failing to shoot a glass shiny christmas tree "bubble/ball", I am wondering how do you manage to avoid most reflections on your latex shots.<br/> <br/>Regarding this shoot, it is quite good. The composition is centered, but the "cornered eyes" are making center position quite suitable.<br/>I would have perhaps liked to see more details on the furr.</td>', 'After failing to shoot a glass shiny christmas tree "bubble/ball", I am wondering how do you manage to avoid most reflections on your latex shots. Regarding this shoot, it is quite good. The composition is centered, but the "cornered eyes" are making center position quite suitable.I would have perhaps liked to see more details on the furr.', '2004-12-20 17:43:40.000000', NULL, 1),
(1071245, 129323, 20779, '<td valign="top">Classy is the key word here. Wow.</td>', 'Classy is the key word here. Wow.', '2004-12-20 19:57:29.000000', NULL, 1),
(1071249, 129034, 20779, '<td valign="top">Please post your editing process at the end - I love the classic, nostalgic look you achieved. I have never seen anything quite like this and it is just perfect for the subject and image.</td>', 'Please post your editing process at the end - I love the classic, nostalgic look you achieved. I have never seen anything quite like this and it is just perfect for the subject and image.', '2004-12-20 19:58:59.000000', NULL, 1),
(1071252, 129196, 20779, '<td valign="top">Stunning texture, DOF and lighting. Your filling of the frame is just right and very effective.</td>', 'Stunning texture, DOF and lighting. Your filling of the frame is just right and very effective.', '2004-12-20 20:00:08.000000', NULL, 1),
(1071253, 129110, 20779, '<td valign="top">Pure class.</td>', 'Pure class.', '2004-12-20 20:00:24.000000', NULL, 1),
(1071257, 129301, 20779, '<td valign="top">What beautiful tones and texture you kept here. I love the abstract placement within the frame - very engaging. I see a lot of "noise" or "grain", which I think enhances the image and gives it a warm, nostalgic feel.</td>', 'What beautiful tones and texture you kept here. I love the abstract placement within the frame - very engaging. I see a lot of "noise" or "grain", which I think enhances the image and gives it a warm, nostalgic feel.', '2004-12-20 20:01:43.000000', NULL, 1),
(1071259, 129227, 20779, '<td valign="top">The soft glow you gave this image just makes it! Pure class and classic.</td>', 'The soft glow you gave this image just makes it! Pure class and classic.', '2004-12-20 20:02:24.000000', NULL, 1),
(1071261, 129402, 20779, '<td valign="top">Great fish-eye effect to really create an "experience" out of this image.</td>', 'Great fish-eye effect to really create an "experience" out of this image.', '2004-12-20 20:03:03.000000', NULL, 1),
(1071264, 128938, 20779, '<td valign="top">The soft, satiny finish and the graceful composition really are "classy". Well done!!</td>', 'The soft, satiny finish and the graceful composition really are "classy". Well done!!', '2004-12-20 20:03:58.000000', NULL, 1),
(1071266, 129278, 20779, '<td valign="top">Simply intriguing image. Very creative, and kept "classy" with the soft, velvety lighting and tones.</td>', 'Simply intriguing image. Very creative, and kept "classy" with the soft, velvety lighting and tones.', '2004-12-20 20:04:56.000000', NULL, 1),
