(1071268, 129060, 20779, '<td valign="top">Perfect simplicity in composition, tone and texture. Classy? Absolutely!</td>', 'Perfect simplicity in composition, tone and texture. Classy? Absolutely!', '2004-12-20 20:05:58.000000', NULL, 1),
(1071270, 129437, 20779, '<td valign="top">Gorgeous take. Her eyes say it all. I am not sure if I think the ring adds just the right "spark" or creates the slightest of distractions. Either way, of no consequence - fantastic holiday portrait.</td>', 'Gorgeous take. Her eyes say it all. I am not sure if I think the ring adds just the right "spark" or creates the slightest of distractions. Either way, of no consequence - fantastic holiday portrait.', '2004-12-20 20:07:29.000000', NULL, 1),
(1071272, 129401, 20779, '<td valign="top">The image is obviously classy and engaging - and your title really adds a clever creativity.</td>', 'The image is obviously classy and engaging - and your title really adds a clever creativity.', '2004-12-20 20:08:19.000000', NULL, 1),
(1071273, 129165, 20779, '<td valign="top">I love the bold neon blue on stark black. Crisp and elegant.</td>', 'I love the bold neon blue on stark black. Crisp and elegant.', '2004-12-20 20:09:05.000000', NULL, 1),
