(1071493, 129117, 25464, '<td valign="top">One of the classiest in the challenge. The bow is a little busy, but an overall very nice shot. 9.</td>', 'One of the classiest in the challenge. The bow is a little busy, but an overall very nice shot. 9.', '2004-12-21 00:18:55.000000', NULL, 1),
(1071497, 129194, 25464, '<td valign="top">I think the lights themselves are a bit overdone, but the angle that you used and the reflection from the ground add a little class here. 8.</td>', 'I think the lights themselves are a bit overdone, but the angle that you used and the reflection from the ground add a little class here. 8.', '2004-12-21 00:20:19.000000', NULL, 1),
(1071498, 129402, 25464, '<td valign="top">Beautiful choice.  Classy, unique, and well done. 8.</td>', 'Beautiful choice.  Classy, unique, and well done. 8.', '2004-12-21 00:21:03.000000', NULL, 1),
(1071500, 129196, 25464, '<td valign="top">This is very nice.  Interesting ornament, nice lighting and processing.  I think it would have been better had you added a bit of ribbon to the top ot the ornament, but very nicely done. 8.</td>', 'This is very nice.  Interesting ornament, nice lighting and processing.  I think it would have been better had you added a bit of ribbon to the top ot the ornament, but very nicely done. 8.', '2004-12-21 00:22:34.000000', NULL, 1),
(1071502, 129171, 25464, '<td valign="top">I am still not sure what I am looking at here, but is has lovely lines and movement and definitely appears to have class.  Interesting abstract approach. 8.</td>', 'I am still not sure what I am looking at here, but is has lovely lines and movement and definitely appears to have class.  Interesting abstract approach. 8.', '2004-12-21 00:23:36.000000', NULL, 1),
(1071504, 129181, 25464, '<td valign="top">I moved this one around a bit before settling on 8.  The trees and silhouettes are very interesting, but I think it would have been better to get a lower angle to include less ground and set the forms of the people more in the lit tree background.  I also find the small bits of color visible in the trees and directly down the path a bit distracting.  Still very nice and one of the better shots in the challenge.</td>', 'I moved this one around a bit before settling on 8.  The trees and silhouettes are very interesting, but I think it would have been better to get a lower angle to include less ground and set the forms of the people more in the lit tree background.  I also find the small bits of color visible in the trees and directly down the path a bit distracting.  Still very nice and one of the better shots in the challenge.', '2004-12-21 00:26:22.000000', NULL, 1),
(1071505, 128965, 25464, '<td valign="top">This is very nice, but I would have liked to see the "CH" on Christmas more plainly, and see less stark white background.  Very nice idea. 7.</td>', 'This is very nice, but I would have liked to see the "CH" on Christmas more plainly, and see less stark white background.  Very nice idea. 7.', '2004-12-21 00:27:55.000000', NULL, 1),
(1071512, 129457, 25464, '<td valign="top">I really like this shot, but feel it is missing something.  Perhaps it needs more dramatic lighting.  Regardless, nice shot. 7.</td>', 'I really like this shot, but feel it is missing something.  Perhaps it needs more dramatic lighting.  Regardless, nice shot. 7.', '2004-12-21 00:33:57.000000', NULL, 1),
(1071513, 129076, 25464, '<td valign="top">This really seems a bit over the top to be considered classy.  It also feels really crowded in the frame.  The top of the building and tree are clipped, and no space is allowed on either side. 5.</td>', 'This really seems a bit over the top to be considered classy.  It also feels really crowded in the frame.  The top of the building and tree are clipped, and no space is allowed on either side. 5.', '2004-12-21 00:35:44.000000', NULL, 1),
