(1075905, 129437, 30861, '<td valign="top">I wonder if the gal sees herself as a classy decoration? this gets a prize for sexism anyway, LOL. The determined horizontal of the right arm seems overdone here, I wish it had more of a sweet angle. well-lit and composed otherwise.</td>', 'I wonder if the gal sees herself as a classy decoration? this gets a prize for sexism anyway, LOL. The determined horizontal of the right arm seems overdone here, I wish it had more of a sweet angle. well-lit and composed otherwise.', '2004-12-23 21:41:00.000000', NULL, 1),
(1075908, 129076, 30861, '<td valign="top">This would be fine, a very good "light photo", if it had a bit of breathing room at the top.</td>', 'This would be fine, a very good "light photo", if it had a bit of breathing room at the top.', '2004-12-23 21:41:36.000000', NULL, 1),
