INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1075931, 129057, 30861, '<td valign="top">very nicely-done light shot</td>', 'very nicely-done light shot', '2004-12-23 21:49:22.000000', NULL, 1),
(1075932, 129366, 30861, '<td valign="top">ah this is sweet. would it work better if the light leaf center left were taken down a zone?</td>', 'ah this is sweet. would it work better if the light leaf center left were taken down a zone?', '2004-12-23 21:49:58.000000', NULL, 1),
(1075936, 129047, 30861, '<td valign="top">NOTHING is happening here.  I don''t see xmas at all. the cropping seems utterly arbitrary, too.</td>', 'NOTHING is happening here.  I don''t see xmas at all. the cropping seems utterly arbitrary, too.', '2004-12-23 21:50:57.000000', NULL, 1),
(1075939, 128983, 30861, '<td valign="top">I''d expect this one to glow a lot more than it does. amp up the luminosity and let it sing.</td>', 'I''d expect this one to glow a lot more than it does. amp up the luminosity and let it sing.', '2004-12-23 21:51:36.000000', NULL, 1),
(1075944, 129255, 30861, '<td valign="top">cropping is very arbitary. almost impossible to shoot this with the sole light source contained in the picture. This would have rewarded more experimentation with key lights etc.</td>', 'cropping is very arbitary. almost impossible to shoot this with the sole light source contained in the picture. This would have rewarded more experimentation with key lights etc.', '2004-12-23 21:53:05.000000', NULL, 1),
(1075945, 129305, 30861, '<td valign="top">clean and simple. I like it. I might have saturated a hair more across the spectrum.</td>', 'clean and simple. I like it. I might have saturated a hair more across the spectrum.', '2004-12-23 21:53:40.000000', NULL, 1),
(1075947, 129457, 30861, '<td valign="top">the composition is forcing my eye up and out to the background ball, and it''s not in focus, so the image is failing for me. it needs a more effective composition.</td>', 'the composition is forcing my eye up and out to the background ball, and it''s not in focus, so the image is failing for me. it needs a more effective composition.', '2004-12-23 21:55:05.000000', NULL, 1),
(1075950, 129335, 30861, '<td valign="top">it doesn''t say "xmas" for me, especially since the very shallow depth-of-field leaves only the candle wick/black stem sharp, and how can THAT be the point of this image?</td>', 'it doesn''t say "xmas" for me, especially since the very shallow depth-of-field leaves only the candle wick/black stem sharp, and how can THAT be the point of this image?', '2004-12-23 21:56:24.000000', NULL, 1),
(1075953, 129490, 30861, '<td valign="top">nice light shot. wish there was a little more detail connecting the orphaned, dimmer lights upper right to the mass.</td>', 'nice light shot. wish there was a little more detail connecting the orphaned, dimmer lights upper right to the mass.', '2004-12-23 21:57:05.000000', NULL, 1),
(1075954, 129489, 30861, '<td valign="top">there''s no compositional point to this image; it refuses to take me anywhere</td>', 'there''s no compositional point to this image; it refuses to take me anywhere', '2004-12-23 21:57:41.000000', NULL, 1),
(1075958, 129253, 30861, '<td valign="top">very awkward compositokin, this cries out to be vertical with more foreground. the aftermarket, black frame is a very negative presence, too, since it can only be seen on the bottom edge and looks like a cropping mistake.</td>', 'very awkward compositokin, this cries out to be vertical with more foreground. the aftermarket, black frame is a very negative presence, too, since it can only be seen on the bottom edge and looks like a cropping mistake.', '2004-12-23 21:58:57.000000', NULL, 1),
