(1075973, 129345, 30861, '<td valign="top">a winner int he title category. I wish it were crisper</td>', 'a winner int he title category. I wish it were crisper', '2004-12-23 22:03:13.000000', NULL, 1),
(1075975, 129330, 30861, '<td valign="top">be nice if you''d taken the trouble to provide some contextual background to this. It''s nice to see a dreidl, though.</td>', 'be nice if you''d taken the trouble to provide some contextual background to this. It''s nice to see a dreidl, though.', '2004-12-23 22:03:56.000000', NULL, 1),
(1075976, 129491, 30861, '<td valign="top">completely out of focus, wimpy background, arbitrary cropping.</td>', 'completely out of focus, wimpy background, arbitrary cropping.', '2004-12-23 22:04:41.000000', NULL, 1),
(1075977, 128997, 30861, '<td valign="top">juice it up tempo a little. there''s a lot of potential here but the tonal range needs expanding on the figure itself.</td>', 'juice it up tempo a little. there''s a lot of potential here but the tonal range needs expanding on the figure itself.', '2004-12-23 22:05:31.000000', NULL, 1),
(1075983, 129293, 30861, '<td valign="top">this has a kind of Diane Arbus feel to it, except it''s a tree instead of a human. I think it''s an exquisite image. I might take just a HAIR off the top. as an architectural photographer (retired) I greatly appreciate what you''ve accomplished here. First "10" I have handed out.</td>', 'this has a kind of Diane Arbus feel to it, except it''s a tree instead of a human. I think it''s an exquisite image. I might take just a HAIR off the top. as an architectural photographer (retired) I greatly appreciate what you''ve accomplished here. First "10" I have handed out.', '2004-12-23 22:08:26.000000', NULL, 1),
(1075984, 129276, 30861, '<td valign="top">this could have been sweet, but it''s muddy, it feels crooked (needs rotating to left), it just isn''t working well. nice concept though.</td>', 'this could have been sweet, but it''s muddy, it feels crooked (needs rotating to left), it just isn''t working well. nice concept though.', '2004-12-23 22:09:15.000000', NULL, 1),
(1075986, 128985, 30861, '<td valign="top">classy as hell and nicely done</td>', 'classy as hell and nicely done', '2004-12-23 22:09:37.000000', NULL, 1),
