(1075990, 129467, 30861, '<td valign="top">I''d love this if the window weren''t there, but it''s a bad eyetrap for me.</td>', 'I''d love this if the window weren''t there, but it''s a bad eyetrap for me.', '2004-12-23 22:10:46.000000', NULL, 1),
(1075991, 129303, 30861, '<td valign="top">oh wow! excellent light-shot. a little more foreground would have beennice, and maybe crop out the distracting light blob on the left?</td>', 'oh wow! excellent light-shot. a little more foreground would have beennice, and maybe crop out the distracting light blob on the left?', '2004-12-23 22:11:36.000000', NULL, 1),
(1075994, 129032, 30861, '<td valign="top">I wish the moon were up and left a little</td>', 'I wish the moon were up and left a little', '2004-12-23 22:12:27.000000', NULL, 1),
(1075996, 129376, 30861, '<td valign="top">seems kind of confused to me</td>', 'seems kind of confused to me', '2004-12-23 22:12:47.000000', NULL, 1),
(1075999, 129129, 30861, '<td valign="top">it may be the tallest decorated tree, but this comes across as a photo of the most banal motel in the country to me</td>', 'it may be the tallest decorated tree, but this comes across as a photo of the most banal motel in the country to me', '2004-12-23 22:13:30.000000', NULL, 1),
(1076000, 129227, 30861, '<td valign="top">key, kewl. Another Arbus tree. I like this a lot. Here, the slight muddiness of the hues is working for, not against, the image.</td>', 'key, kewl. Another Arbus tree. I like this a lot. Here, the slight muddiness of the hues is working for, not against, the image.', '2004-12-23 22:14:17.000000', NULL, 1),
