(1076012, 129465, 30861, '<td valign="top">it''s nicely done, but it doesn''t say "xmas" to me</td>', 'it''s nicely done, but it doesn''t say "xmas" to me', '2004-12-23 22:20:37.000000', NULL, 1),
(1076013, 129282, 30861, '<td valign="top">this is screaming out for some serious fill light and key lights. sheesh. we have a photo of burnt-out windows here, is what we have</td>', 'this is screaming out for some serious fill light and key lights. sheesh. we have a photo of burnt-out windows here, is what we have', '2004-12-23 22:21:25.000000', NULL, 1),
(1076015, 129228, 30861, '<td valign="top">elegantly composed, powerful and massive</td>', 'elegantly composed, powerful and massive', '2004-12-23 22:21:51.000000', NULL, 1),
